"""Generate a Vibe-Trading ``signal_engine.py`` from a :class:`SignalSpec`.

Vibe-Trading loads a strategy from ``<run_dir>/code/signal_engine.py`` but first
runs an AST safety scan (``runner._validate_signal_engine_source``). The rules:

* top level may only contain imports, function defs, class defs, literal-only
  assignments, and a docstring — **no** ``if __name__ == "__main__"`` or any
  other executable statement;
* functions/classes may not use decorators; function default args must be
  literals and annotations must be plain references;
* the class must be named ``SignalEngine``, be instantiable with no args
  (all ``__init__`` params defaulted), and expose ``generate()``.

Strategy: keep the entire engine body as one *fixed* template (already known to
pass the scan) and inject only literal default values into ``__init__``. The
spec's numbers (target weight, holding days, RSI thresholds, MACD-cross gates,
stop-loss) all round-trip through ``repr`` as Python literals, so the generated
file is deterministic and always contract-valid.
"""

from __future__ import annotations

import ast

from .signal_spec import EntryCondition, SignalSpec

# --- the fixed engine body (validated once, reused verbatim) ----------------
#
# Everything below the __init__ signature is static. compute_rsi mirrors
# Vibe-Trading's own Wilder-EWM implementation so backtest RSI matches the
# indicator the analysts reasoned about.

_TEMPLATE = '''"""Auto-generated by ta_vibe_bridge from a TradingAgents decision.

{docstring}

DO NOT EDIT BY HAND — regenerate from the SignalSpec instead.
"""

from typing import Dict, List

import numpy as np
import pandas as pd


def compute_rsi(close: pd.Series, period: int = 14) -> pd.Series:
    """RSI via Wilder EWM smoothing (matches Vibe-Trading's technical-basic)."""
    delta = close.diff()
    gain = delta.clip(lower=0)
    loss = (-delta).clip(lower=0)
    avg_gain = gain.ewm(alpha=1 / period, min_periods=period).mean()
    avg_loss = loss.ewm(alpha=1 / period, min_periods=period).mean()
    rs = avg_gain / avg_loss
    return 100 - 100 / (1 + rs)


def compute_macd(close: pd.Series, fast: int = 12, slow: int = 26, signal: int = 9) -> pd.DataFrame:
    """MACD line (fast EMA - slow EMA) and its signal line (EMA of MACD)."""
    ema_fast = close.ewm(span=fast, adjust=False).mean()
    ema_slow = close.ewm(span=slow, adjust=False).mean()
    macd_line = ema_fast - ema_slow
    signal_line = macd_line.ewm(span=signal, adjust=False).mean()
    return pd.DataFrame({{"macd": macd_line, "signal": signal_line}})


def compute_sma(close: pd.Series, window: int = 50) -> pd.Series:
    """Simple moving average."""
    return close.rolling(window).mean()


class SignalEngine:
    """Directional / conditional engine derived from a TradingAgents decision.

    With no entry conditions the engine holds ``target_weight`` for the whole
    period (a faithful test of the directional call). With conditions it enters
    ``target_weight`` only on bars where every gate holds, holds for
    ``holding_days`` bars, then flattens — with an optional stop expressed as a
    percentage move against each trade's own entry price.
    """

    def __init__(
        self,
{init_defaults}
    ):
        self.target_weight = float(target_weight)
        self.holding_days = holding_days
        self.rsi_period = rsi_period
        self.macd_fast = macd_fast
        self.macd_slow = macd_slow
        self.macd_signal = macd_signal
        self.stop_pct = stop_pct
        self.confirm_window = confirm_window
        self.entry_conditions = entry_conditions

    def generate(self, data_map: Dict[str, pd.DataFrame]) -> Dict[str, pd.Series]:
        out = {{}}
        for code, df in data_map.items():
            out[code] = self._generate_one(df)
        return out

    def _within_window(self, mask: pd.Series) -> pd.Series:
        """True on bars where ``mask`` held on this or any of the prior
        ``confirm_window - 1`` bars. Turns an instantaneous trigger (a MACD
        cross) into a short-lived setup so a separate condition (RSI < 30) can
        line up with it within a window instead of on the exact same bar."""
        if self.confirm_window <= 1:
            return mask.fillna(False)
        held = mask.fillna(False).astype(int)
        return held.rolling(self.confirm_window, min_periods=1).max().astype(bool)

    def _entry_mask(self, df: pd.DataFrame) -> pd.Series:
        close = df["close"]
        masks = []
        for kind, value in self.entry_conditions:
            if kind == "rsi_below":
                masks.append(compute_rsi(close, self.rsi_period) < value)
            elif kind == "rsi_above":
                masks.append(compute_rsi(close, self.rsi_period) > value)
            elif kind == "macd_golden_cross":
                m = compute_macd(close, self.macd_fast, self.macd_slow, self.macd_signal)
                masks.append((m["macd"].shift(1) <= m["signal"].shift(1)) & (m["macd"] > m["signal"]))
            elif kind == "macd_death_cross":
                m = compute_macd(close, self.macd_fast, self.macd_slow, self.macd_signal)
                masks.append((m["macd"].shift(1) >= m["signal"].shift(1)) & (m["macd"] < m["signal"]))
            elif kind == "price_above_sma":
                masks.append(close > compute_sma(close, int(value)))
            elif kind == "price_below_sma":
                masks.append(close < compute_sma(close, int(value)))
        if not masks:
            return pd.Series(True, index=df.index)
        # Each condition is satisfied if it held anywhere in the confirm window;
        # entry fires on a bar where every condition is jointly satisfied.
        mask = self._within_window(masks[0])
        for extra in masks[1:]:
            mask = mask & self._within_window(extra)
        return mask.fillna(False)

    def _generate_one(self, df: pd.DataFrame) -> pd.Series:
        close = df["close"]
        entry = self._entry_mask(df)
        entry_arr = entry.to_numpy()
        close_arr = close.to_numpy()
        weights = np.zeros(len(df), dtype=float)
        remaining = 0
        entry_price = 0.0
        long_side = self.target_weight > 0
        for i in range(len(entry_arr)):
            if remaining <= 0 and bool(entry_arr[i]):
                remaining = self.holding_days
                # Position is executed next bar at open by the engine, but the
                # decision price we anchor the stop to is this bar's close.
                entry_price = close_arr[i]
            if remaining > 0:
                # Percentage stop relative to *this trade's* entry price, so the
                # rule is regime-independent across a multi-year backtest (an
                # absolute price level from the decision date would be
                # meaningless years earlier). stop_pct is None -> no stop.
                if self.stop_pct is not None and entry_price > 0:
                    move = (close_arr[i] - entry_price) / entry_price
                    if long_side and move <= -self.stop_pct:
                        remaining = 0
                        continue
                    if (not long_side) and move >= self.stop_pct:
                        remaining = 0
                        continue
                weights[i] = self.target_weight
                remaining -= 1
        return pd.Series(weights, index=df.index)
'''


def _entry_conditions_literal(conditions: list[EntryCondition]) -> str:
    """Render entry conditions as a Python tuple-of-tuples literal.

    Empty -> ``()``. Each condition -> ``("kind", value)`` where value is a
    float literal or ``None``. Only literals so the AST scanner accepts it as a
    default argument.
    """
    if not conditions:
        return "()"
    parts = []
    for c in conditions:
        value_repr = "None" if c.value is None else repr(float(c.value))
        parts.append(f'("{c.kind}", {value_repr})')
    inner = ", ".join(parts)
    # Trailing comma keeps a single-element tuple a tuple, not a grouping paren.
    return f"({inner},)"


def _init_defaults_block(spec: SignalSpec) -> str:
    """Build the indented, literal-only ``__init__`` default arguments."""
    stop = "None" if spec.stop_pct is None else repr(float(spec.stop_pct))
    lines = [
        # Vibe's runner accepts AST constants but rejects a negative number's
        # UnaryOp node. Keep every generated weight as a string constant and
        # convert it inside the fixed engine body.
        f"        target_weight: str = {repr(str(float(spec.target_weight)))},",
        f"        holding_days: int = {int(spec.holding_days)},",
        "        rsi_period: int = 14,",
        "        macd_fast: int = 12,",
        "        macd_slow: int = 26,",
        "        macd_signal: int = 9,",
        f"        stop_pct = {stop},",
        f"        confirm_window: int = {int(spec.confirm_window)},",
        f"        entry_conditions = {_entry_conditions_literal(spec.entry_conditions)},",
    ]
    return "\n".join(lines)


def generate_signal_engine_source(spec: SignalSpec) -> str:
    """Render a contract-valid ``signal_engine.py`` source string for ``spec``."""
    source = _TEMPLATE.format(
        docstring=spec.summary(),
        init_defaults=_init_defaults_block(spec),
    )
    # Fail fast in-process rather than only at backtest time.
    assert_vibe_ast_safe(source)
    return source


# --- local mirror of Vibe-Trading's AST scan (so we can self-test) ----------
#
# Replicates runner._validate_signal_engine_source closely enough to catch a
# generated file that would be rejected, without importing Vibe (which pulls in
# pandas). Kept intentionally strict.


def _is_literal(node: ast.AST) -> bool:
    if isinstance(node, ast.Constant):
        return True
    if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
        return all(_is_literal(e) for e in node.elts)
    if isinstance(node, ast.Dict):
        return all(
            (k is None or _is_literal(k)) and _is_literal(v)
            for k, v in zip(node.keys, node.values)
        )
    # Allow unary minus on a numeric literal, e.g. -0.5.
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return _is_literal(node.operand)
    return False


def _is_safe_reference(node: ast.AST | None) -> bool:
    if node is None:
        return True
    if isinstance(node, (ast.Name, ast.Attribute, ast.Constant)):
        return True
    if isinstance(node, ast.Subscript):
        return _is_safe_reference(node.value) and _is_safe_reference(node.slice)
    if isinstance(node, ast.Tuple):
        return all(_is_safe_reference(e) for e in node.elts)
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitOr):
        return _is_safe_reference(node.left) and _is_safe_reference(node.right)
    return False


def _check_function(node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
    if node.decorator_list:
        raise ValueError(f"decorator on function {node.name!r}")
    for default in [*node.args.defaults, *[d for d in node.args.kw_defaults if d]]:
        if not _is_literal(default):
            raise ValueError(f"non-literal default on function {node.name!r}")


def _check_class(node: ast.ClassDef) -> None:
    if node.decorator_list:
        raise ValueError(f"decorator on class {node.name!r}")
    for base in node.bases:
        if not _is_safe_reference(base):
            raise ValueError(f"unsafe base on class {node.name!r}")
    if node.keywords:
        raise ValueError(f"class keywords on {node.name!r}")
    for child in node.body:
        if isinstance(child, ast.Expr) and isinstance(child.value, ast.Constant):
            continue
        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _check_function(child)
            continue
        if isinstance(child, ast.Pass):
            continue
        if isinstance(child, ast.Assign) and _is_literal(child.value):
            continue
        if isinstance(child, ast.AnnAssign) and (child.value is None or _is_literal(child.value)):
            continue
        raise ValueError(f"executable class-level statement {type(child).__name__}")


def assert_vibe_ast_safe(source: str) -> None:
    """Raise ``ValueError`` if ``source`` would fail Vibe-Trading's AST scan.

    Mirrors ``runner._validate_signal_engine_source``. Also asserts the module
    defines a class named ``SignalEngine`` — the name the runner looks up.
    """
    try:
        tree = ast.parse(source)
    except SyntaxError as exc:  # pragma: no cover - template is static
        raise ValueError(f"invalid syntax: {exc}") from exc

    has_engine = False
    for node in tree.body:
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
            continue
        if isinstance(node, ast.ImportFrom) and node.module == "signal_engine":
            raise ValueError("circular import from signal_engine")
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            continue
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _check_function(node)
            continue
        if isinstance(node, ast.ClassDef):
            if node.name == "SignalEngine":
                has_engine = True
            _check_class(node)
            continue
        if isinstance(node, ast.Assign) and _is_literal(node.value):
            continue
        if isinstance(node, ast.AnnAssign) and (node.value is None or _is_literal(node.value)):
            continue
        raise ValueError(f"executable top-level statement {type(node).__name__}")

    if not has_engine:
        raise ValueError("no class named 'SignalEngine' defined")
